def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if 100 - n <= 2:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_def = sum(1 for x in opp if x == 'D')
    my_def = sum(1 for x in me if x == 'D')

    # Early aggression: if opponent defected in first 3 rounds, they are likely aggressive
    if n >= 3:
        early_opp_def = sum(1 for x in opp[:3] if x == 'D')
        if early_opp_def >= 2:
            if n >= 2 and opp[-1] == 'C' and opp[-2] == 'C':
                return 'C'
            return 'D'

    # Find first time we defected
    first_my_def = -1
    for i, a in enumerate(me):
        if a == 'D':
            first_my_def = i
            break

    if first_my_def == -1:
        if n < 5:
            return 'C'
        return 'D'

    # We have tested. Check opponent's response to our first defection.
    if first_my_def + 1 < n:
        response = opp[first_my_def + 1]
        if response == 'D':
            # Retaliatory opponent: forgiving tit-for-tat
            last_me = me[-1]
            last_opp = opp[-1]
            if last_opp == 'D':
                recent_my_def = False
                if len(me) >= 2:
                    if me[-1] == 'D' or me[-2] == 'D':
                        recent_my_def = True
                elif len(me) >= 1:
                    if me[-1] == 'D':
                        recent_my_def = True
                if recent_my_def:
                    return 'C'
                else:
                    return 'D'
            else:
                return 'C'
        else:
            # Non-retaliatory opponent: exploit
            last_me = me[-1]
            last_opp = opp[-1]
            if last_opp == 'D':
                if last_me == 'D':
                    return 'C'
                else:
                    return 'D'
            else:
                return 'D'

    # If we haven't seen the response yet, continue defecting
    return 'D'
